int main() {
    FILE *fp;
    char ch;
    int lines = 0, words = 0, chars = 0;
    int in_word = 0;

    if ((fp = fopen("text.txt", "r")) == NULL) {
        printf("无法打开文件\n");
        exit(1);
    }

    while ((ch = fgetc(fp)) != EOF) {
        chars++;
        if (ch == '\n') lines++;

        if (isspace(ch)) {
            in_word = 0;
        } else if (!in_word) {
            in_word = 1;
            words++;
        }
    }
    // 如果文件非空且最后一行没有换行符，行数通常加1或者视定义而定，这里按换行符个数统计
    if (chars > 0 && ch != '\n') lines++; 

    fclose(fp);
    printf("行数: %d, 字数: %d, 字符数: %d\n", lines, words, chars);
    return 0;
}

